// app/review/route.ts — serves the migration review page (live site × new, side by side) at /review.
// The HTML is generated by tools/migrate/review/build-review.mjs into ./review-html.ts; regenerate after every batch
// of fixes. Never indexed: noindex here (header + meta), disallowed in robots.txt, kept out of the sitemap.
// Optional password: REVIEW_PASSWORD + the Basic Auth check of review-auth.ts in proxy.ts / middleware.ts.
// Remove it (or keep it protected and unlinked) before the final handoff if the client prefers.
import { REVIEW_HTML } from "./review-html";

// Built once at `next build`; a production server needs a rebuild to show a regenerated page (dev picks it up).
export const dynamic = "force-static";

export function GET() {
  return new Response(REVIEW_HTML, {
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "X-Robots-Tag": "noindex, nofollow, noarchive, noimageindex",
      // Private: never stored by shared caches (it may sit behind Basic Auth); browsers revalidate on each visit.
      "Cache-Control": "private, no-cache, max-age=0, must-revalidate",
      "Referrer-Policy": "no-referrer",
    },
  });
}
